import { lazy, Suspense } from "react";
import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { Routes, Route } from "react-router-dom";
import BranchContactProvider from "@/components/BranchContactProvider";
import StructuredData from "@/components/StructuredData";

/**
 * Client app — all page routes are lazy so visiting /frames does not download
 * the homepage Index chunk (and vice versa). `main.tsx` preloads the active
 * route before hydrateRoot. Prerender uses sync `AppPrerender.tsx`.
 */
const Index = lazy(() => import("@/pages/Index"));
const About = lazy(() => import("@/pages/About"));
const FrameCatalog = lazy(() => import("@/pages/FrameCatalog"));
const LearnAboutEyes = lazy(() => import("@/pages/LearnAboutEyes"));
const NotFound = lazy(() => import("@/pages/NotFound"));

const App = () => (
  <TooltipProvider>
    <Toaster />
    <Sonner />
    <BranchContactProvider>
      <StructuredData />
      <Suspense fallback={null}>
        <Routes>
          <Route path="/" element={<Index />} />
          <Route path="/about" element={<About />} />
          <Route path="/frames" element={<FrameCatalog />} />
          <Route path="/learn" element={<LearnAboutEyes />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Suspense>
    </BranchContactProvider>
  </TooltipProvider>
);

export default App;
